schema.content:
Table "advisedBy" {
  "p_id" INTEGER [pk]
  "p_id_dummy" INTEGER [pk]
}

Table "course" {
  "course_id" INTEGER [pk]
  "courseLevel" TEXT
}

Table "person" {
  "p_id" INTEGER [pk]
  "professor" INTEGER
  "student" INTEGER
  "hasPosition" TEXT
  "inPhase" TEXT
  "yearsInProgram" TEXT
}

Table "taughtBy" {
  "course_id" INTEGER [pk]
  "p_id" INTEGER [pk]
}



Ref: "advisedBy"."p_id" > "person"."p_id"

Ref: "advisedBy"."p_id_dummy" > "person"."p_id"

Ref: "taughtBy"."course_id" > "course"."course_id"

Ref: "taughtBy"."p_id" > "person"."p_id"
